True def transform(grid):
    out = [row[:] for row in grid]
    background = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] != background and row[c + 1] == background and row[c + 2] != background:
                out[r][c + 1] = 2
    return out
